import{_ as a,c as s,o as n,ae as i}from"./chunks/framework.DEXG3EuZ.js";const u=JSON.parse('{"title":"Backend integration","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/backend.md","filePath":"en/guide/backend.md","lastUpdated":1792605191000}'),t={name:"en/guide/backend.md"};function o(r,e,c,d,p,l){return n(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="backend-integration" tabindex="-1">Backend integration <a class="header-anchor" href="#backend-integration" aria-label="Permalink to &quot;Backend integration&quot;">​</a></h1><p>The business service runs Go/Gin on 8002 and owns authentication, products and favorites; FastAPI runs on 8001 and owns AI JSON/SSE. Start each service using its own quick-start instructions, then run the frontend with the committed <code>.env.integration</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VITE_USE_MOCK=false</span></span>
<span class="line"><span>VITE_API_BASE_URL=/api</span></span>
<span class="line"><span>VITE_AI_API_BASE_URL=/api/ai</span></span>
<span class="line"><span>VITE_API_TARGET=http://127.0.0.1:8002</span></span>
<span class="line"><span>VITE_AI_API_TARGET=http://127.0.0.1:8001</span></span>
<span class="line"><span>VITE_REQUEST_ID_ENABLED=true</span></span>
<span class="line"><span>VITE_PWA_ENABLED=false</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:integration</span></span></code></pre></div><h2 id="contract-differences-to-resolve" tabindex="-1">Contract differences to resolve <a class="header-anchor" href="#contract-differences-to-resolve" aria-label="Permalink to &quot;Contract differences to resolve&quot;">​</a></h2><p>The Vite proxy forwards requests; it does not translate API contracts. Before treating a full browser flow as integrated, reconcile these differences:</p><ul><li>Login: frontend sends <code>name</code> and reads <code>token</code>; Gin expects <code>username</code> and returns <code>accessToken</code>.</li><li>Profile: frontend requests <code>/api/user/profile</code>; Gin exposes <code>/api/user/info</code>.</li><li>Catalog: frontend requests <code>/api/products</code> and <code>/api/products/:id</code>, using localized <code>name</code> and <code>priceCents</code>; Gin exposes <code>/api/product/list</code> and <code>/api/product/detail?id=…</code>, returning <code>title</code> and <code>price</code>.</li><li>Project CRUD exists in the frontend contract, but the current Gin router does not register Project endpoints.</li></ul><h2 id="new-feature-boundaries" tabindex="-1">New feature boundaries <a class="header-anchor" href="#new-feature-boundaries" aria-label="Permalink to &quot;New feature boundaries&quot;">​</a></h2><p>The favorite GET/POST paths match Gin, but require a Gin-issued JWT and an existing public product ID. A frontend Mock token is not valid for the real services. AI suggestions are public JSON and can be checked independently of login. The browser session cannot be assumed integrated simply because the transport accepts the service envelope.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Use API-level checks below before browser integration. Obtain <code>BUSINESS_USER_JWT</code> from the business service’s actual login response; use its development account configuration, not old documentation credentials. Browser E2E against Mock does not establish real database or cross-service integration.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:8001/api/ai/suggestions?locale=ja-JP&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:8002/api/product/favorite?id=1&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BUSINESS_USER_JWT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p><a href="./request">API</a> · <a href="./ai-chat">AI Chat</a> · <a href="./commerce">Commerce</a></p>`,13)])])}const k=a(t,[["render",o]]);export{u as __pageData,k as default};
